import { useCallback, useEffect, useMemo, useState } from 'react';
import { useLocation } from 'react-router-dom';

import type { ClaraDomainOption } from 'components/ai/components/molecules/ClaraDomainDropdown';
import { CLARA_VALUE_CREATION_PROJECT_KEY } from 'components/ai/constants/projectKeys';

import {
  buildInitialDomainByRoute,
  getClaraDomainRouteDefault,
  isOptionAvailable,
  LEGACY_CLARA_DOMAIN_OPTION,
  LEGACY_CLARA_DOMAIN_VALUE,
  resolveRouteDefaultValue,
} from './claraDomainRouteDefaults';

interface UseClaraDomainOptions {
  options: ClaraDomainOption[];
  isEnabled: boolean;
  isValueCreationPillarEnabled: boolean;
}

export function useClaraDomain({
  options,
  isEnabled,
  isValueCreationPillarEnabled,
}: UseClaraDomainOptions) {
  const { pathname } = useLocation();
  const routeDefault = useMemo(
    () => getClaraDomainRouteDefault(pathname),
    [pathname],
  );
  const stateKey = routeDefault?.key ?? 'legacy';

  const [domainByRoute, setDomainByRoute] = useState(buildInitialDomainByRoute);
  const [lastSelectedValue, setLastSelectedValue] = useState(
    LEGACY_CLARA_DOMAIN_VALUE,
  );

  const effectiveRouteDefault = useMemo(
    () =>
      resolveRouteDefaultValue(
        stateKey,
        routeDefault,
        isValueCreationPillarEnabled,
        lastSelectedValue,
        options,
      ),
    [
      stateKey,
      routeDefault,
      isValueCreationPillarEnabled,
      lastSelectedValue,
      options,
    ],
  );

  const storedValue = domainByRoute[stateKey];
  const hasStoredValue =
    storedValue !== undefined &&
    isOptionAvailable(storedValue, options) &&
    !(
      stateKey === 'valueCreation' &&
      !isValueCreationPillarEnabled &&
      storedValue === CLARA_VALUE_CREATION_PROJECT_KEY
    );

  const projectKey = isEnabled
    ? hasStoredValue
      ? storedValue
      : effectiveRouteDefault
    : LEGACY_CLARA_DOMAIN_VALUE;

  const dropdownValue = isOptionAvailable(projectKey, options)
    ? projectKey
    : isOptionAvailable(effectiveRouteDefault, options)
      ? effectiveRouteDefault
      : (options.find((option) => option.value === LEGACY_CLARA_DOMAIN_VALUE)
          ?.value ??
        options[0]?.value ??
        LEGACY_CLARA_DOMAIN_VALUE);

  useEffect(() => {
    if (!isEnabled) return;

    setLastSelectedValue(dropdownValue);
  }, [isEnabled, dropdownValue]);

  const selectedClaraDomain = useMemo(
    () =>
      options.find((option) => option.value === dropdownValue) ??
      options.find((option) => option.value === LEGACY_CLARA_DOMAIN_VALUE) ??
      options[0] ??
      LEGACY_CLARA_DOMAIN_OPTION,
    [options, dropdownValue],
  );

  const setSelectedClaraDomain = useCallback(
    (option: ClaraDomainOption) => {
      if (!isEnabled) return;

      setLastSelectedValue(option.value);
      setDomainByRoute((current) => {
        if (current[stateKey] === option.value) return current;

        return {
          ...current,
          [stateKey]: option.value,
        };
      });
    },
    [isEnabled, stateKey],
  );

  return {
    selectedClaraDomain,
    setSelectedClaraDomain,
    projectKey,
    stateKey,
  };
}
